if not os.path.isdir("app") or not os.path.isdir("scripts"):
    sys.exit("Run this from the inner project folder (it must contain the app and scripts folders).")
for path, blob in FILES.items():
    if not os.path.exists(path):
        sys.exit(f"Missing {path}. Are you in the right folder?")
for path, blob in FILES.items():
    shutil.copy2(path, path + ".bak_quality")
    with open(path, "wb") as f:
        f.write(base64.b64decode(blob))
    py_compile.compile(path, doraise=True)
    print("updated", path)
print("\nDone. Restart the server (Ctrl+C, then: uvicorn app.main:app --reload).")